is_unrestricted_ip(val) {
    val.ir_type == "String"
    val.value == "0.0.0.0"
}

is_binding_key(key) {
    key.ir_type == "String"
    regex.match("(?i).*bind.*|.*listen.*|.*host.*|.*ip.*|.*address.*|.*endpoint.*", key.value)
}

is_binding_key(key) {
    key.ir_type == "VariableReference"
    regex.match("(?i).*bind.*|.*listen.*|.*host.*|.*ip.*|.*address.*|.*endpoint.*", key.value)
}

is_binding_key(key) {
    key.ir_type == "Access"
    is_binding_key(key.right)
}
